if(tab==="missions"){const [ad,md]=await Promise.all([api(p+"/agents"),api(p+"/missions")]),agents=arr(ad.agents),missions=arr(md.missions);v.innerHTML='<section class="card"><h2>Nouvelle mission</h2><label>Agent responsable</label><select id="missionAgent" class="field">'+agents.filter(x=>x.status==="active").map(x=>'<option value="'+esc(x.id)+'">'+esc(x.name)+'</option>').join("")+'</select><label>Titre</label><input id="missionTitle" class="field" placeholder="Diagnostic des risques opérationnels"><label>Objectif</label><textarea id="missionObjective" class="field" placeholder="Décrire précisément le travail attendu"></textarea><label>Contexte complémentaire</label><textarea id="missionContext" class="field" placeholder="Informations utiles, contraintes, hypothèses…"></textarea><label>Priorité</label><select id="missionPriority" class="field"><option value="1">1 · Très haute</option><option value="2" selected>2 · Haute</option><option value="3">3 · Normale</option><option value="4">4 · Basse</option><option value="5">5 · Très basse</option></select><button id="missionSubmit" class="btn primary" '+(agents.every(x=>x.status!=="active")?'disabled':'')+'>Enregistrer la mission</button><p class="small">La mission est d’abord enregistrée dans la file serveur. Son exécution dépend de la disponibilité du worker.</p></section><section class="card"><h2>Historique des missions</h2>'+missions.map(x=>'<div class="item"><span><b>'+esc(x.title)+'</b><br><span class="small">'+esc(x.status)+' · priorité '+esc(x.priority)+' · '+esc(x.created_at)+'</span></span><button class="btn" data-mission="'+esc(x.id)+'">Détails</button></div>').join("")+'</section>';if($("missionSubmit"))$("missionSubmit").onclick=()=>api(p+"/missions",{method:"POST",body:JSON.stringify({agentId:$("missionAgent").value,title:$("missionTitle").value,objective:$("missionObjective").value,context:{notes:$("missionContext").value},priority:Number($("missionPriority").value),autonomyLevel:1})}).then(x=>{msg("Mission enregistrée : "+x.mission.status);render()}).catch(e=>msg(e.message));v.querySelectorAll("[data-mission]").forEach(b=>b.onclick=async()=>{try{const d=await api(p+"/missions/"+encodeURIComponent(b.dataset.mission));const m=d.mission;v.innerHTML='<section class="card"><button id="backMissions" class="btn">← Retour</button><h2>'+esc(m.title)+'</h2><p class="small">Statut : '+esc(m.status)+' · Tentatives : '+esc(m.attempt_count)+'</p><h3>Objectif</h3><p>'+esc(m.objective)+'</p><h3>Résultat</h3><pre>'+esc(JSON.stringify(m.result??{},null,2))+'</pre><h3>Journal d’événements</h3>'+arr(d.events).map(e=>'<div class="item">'+esc(e.event_type)+' · '+esc(e.created_at)+'</div>').join("")+'</section>';$("backMissions").onclick=()=>{render().catch(e=>msg(e.message))}}catch(e){msg(e.message)}})}


if(tab==="delegations"){const [ad,md]=await Promise.all([api(p+"/agents"),api(p+"/messages")]),agents=arr(ad.agents),messages=arr(md.messages);const active=agents.filter(x=>x.status==="active");v.innerHTML='<section class="card"><h2>Déléguer une tâche à un autre agent</h2><label>Agent émetteur</label><select id="handoffFrom" class="field">'+active.map(x=>'<option value="'+esc(x.id)+'">'+esc(x.name)+'</option>').join("")+'</select><label>Agent destinataire</label><select id="handoffTo" class="field">'+active.filter(x=>x.id!==active[0]?.id).map(x=>'<option value="'+esc(x.id)+'">'+esc(x.name)+'</option>').join("")+'</select><label>Objet</label><input id="handoffSubject" class="field" placeholder="Revue indépendante de l’analyse"><label>Consigne de délégation</label><textarea id="handoffBody" class="field" placeholder="Travail attendu, périmètre, critères de qualité…"></textarea><button id="handoffSend" class="btn primary" '+(active.length<2?'disabled':'')+'>Envoyer la délégation</button><p class="small">Une délégation crée un message durable. Le worker le convertit en mission pour l’agent destinataire, de manière idempotente.</p></section><section class="card"><h2>Historique des messages inter-agents</h2>'+messages.map(x=>'<div class="item"><span><b>'+esc(x.subject)+'</b><br><span class="small">'+esc(x.message_type)+' · '+esc(x.status)+' · '+esc(x.created_at)+'</span></span></div>').join("")+'</section>';if($("handoffFrom"))$("handoffFrom").onchange=()=>{$("handoffTo").innerHTML=active.filter(x=>x.id!==$("handoffFrom").value).map(x=>'<option value="'+esc(x.id)+'">'+esc(x.name)+'</option>').join("");};if($("handoffSend"))$("handoffSend").onclick=()=>api(p+"/messages",{method:"POST",body:JSON.stringify({fromAgentId:$("handoffFrom").value,toAgentId:$("handoffTo").value,type:"handoff",subject:$("handoffSubject").value,body:{instructions:$("handoffBody").value}})}).then(()=>{msg("Délégation enregistrée dans la file.");render()}).catch(e=>msg(e.message))}
